// World map data (js/data/worldmap.js, generated by tools/build-map.mjs) and the album-derived achievements (js/ui/achievements.js).
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import { COUNTRIES } from '../js/data/countries.js';
import { MAP_W, MAP_H, SHAPES, ANCHORS, DOT_ONLY, TINY, CONTINENT } from '../js/data/worldmap.js';
import { evaluateAchievements, collectionStats, newlyUnlocked, ACHIEVEMENTS } from '../js/ui/achievements.js';
import { S } from '../js/strings.js';

test('the map file is small and every country of the game has a shape or a dot', () => {
  const size = fs.statSync(fileURLToPath(new URL('../js/data/worldmap.js', import.meta.url))).size;
  assert.ok(size <= 150 * 1024, `worldmap.js is ${size} bytes`);
  assert.ok(SHAPES.TWN, 'Taiwan has a shape');
  for (const c of COUNTRIES) {
    assert.ok(SHAPES[c.code] || DOT_ONLY.includes(c.code), `${c.code} ${c.name} has neither shape nor dot`);
    assert.ok(ANCHORS[c.code], `${c.code} has an anchor`);
    assert.ok(['AS', 'EU', 'AF', 'NA', 'SA', 'OC'].includes(CONTINENT[c.code]), `${c.code} continent`);
  }
  for (const code of DOT_ONLY) assert.ok(!SHAPES[code], `${code} is dot-only`);
  for (const code of TINY) assert.ok(SHAPES[code], `${code} tiny implies a shape`);
  for (const [code, [x, y]] of Object.entries(ANCHORS)) assert.ok(x > 0 && x < MAP_W && y > 0 && y < MAP_H, `${code} anchor inside the viewBox`);
  for (const d of Object.values(SHAPES)) assert.match(d, /^M[-\d. ]+l[-\d. zMl]+z$/);
});

const rec = (id, over = {}, meta) => ({
  id, savedAt: 1, message: '', ...(meta ? { meta } : {}),
  summary: {
    name: id, gender: 'F', birthYear: 2000, age: 70, era: 'present', homeCountry: { code: 'TWN', name: '台灣' }, wealthQ: 3, urbanBirth: true,
    countriesLived: ['台灣'], education: { level: 'secondary' }, children: { total: 1 }, yearsWorked: 30, partner: null, marriages: 0, divorces: 0,
    lifespan: { vsCountry: 0 }, ...over,
  },
});

test('achievements derive from album records, old records included', () => {
  const none = evaluateAchievements([]);
  assert.equal(none.length, ACHIEVEMENTS.length);
  assert.ok(none.every((a) => !a.done));
  for (const a of ACHIEVEMENTS) assert.ok(S.ach.items[a.id], `strings for ${a.id}`);

  const done = (list) => new Set(evaluateAchievements(list).filter((a) => a.done).map((a) => a.id));
  assert.ok(done([rec('a')]).has('first_life'));
  assert.ok(done([rec('a')]).has('taiwan'));
  assert.ok(done([rec('a', { age: 101 })]).has('age_100'));
  assert.ok(done([rec('a', { homeCountry: { code: 'MDV', name: '馬爾地夫' } })]).has('tiny_nation'));
  assert.ok(done([rec('a', { countriesLived: ['台灣', '日本', '加拿大'] })]).has('three_countries'));
  assert.ok(done([rec('a', { era: 'past' }), rec('b', { era: 'present' }), rec('c', { era: 'future' })]).has('three_eras'));
  assert.ok(done([rec('a', { gender: 'F' }), rec('b', { gender: 'M' })]).has('both_genders'));
  assert.ok(done([rec('a', { partner: { status: 'married' } }, { partnerYears: 52 })]).has('golden_wedding'));
  assert.ok(!done([rec('a', { partner: { status: 'married' } }, { partnerYears: 30 })]).has('golden_wedding'));
  // an old record without meta: a long, still-standing marriage is estimated from the age
  assert.ok(done([rec('a', { age: 88, partner: { status: 'married' }, marriages: 1, divorces: 0 })]).has('golden_wedding'));
  assert.ok(done([rec('a'), rec('b')]).has('twice_same'));
  // fields missing entirely: no crash, country found by name
  const bare = { id: 'x', summary: { name: 'x', age: 5, homeCountry: { name: '日本' } } };
  assert.doesNotThrow(() => evaluateAchievements([bare]));
  assert.equal(collectionStats([bare]).facts[0].code, 'JPN');
});

test('newlyUnlocked: only what this record adds and what was not announced', () => {
  const a = rec('a'), b = rec('b', { age: 95 });
  assert.deepEqual(newlyUnlocked([a], a, {}), ['first_life', 'taiwan']);
  assert.deepEqual(newlyUnlocked([a], a, { first_life: 1 }), ['taiwan']);
  const ids = newlyUnlocked([a, b], b, {});
  assert.ok(ids.includes('age_90') && ids.includes('twice_same') && !ids.includes('first_life'));
});
